let state = { session:null,sessions:[],participants:[],pilots:[],uavs:[],rounds:[],scenarios:[],flights:[],files:[],transfer_presence:{},connected_users:[],events:[],drone_status:{state:'disconnected',message:'No flight controller connected'},drone_devices:[] };
let selectedSessionId = Number(new URLSearchParams(location.search).get('session_id'))||null;
let currentView = new URLSearchParams(location.search).get('sd_transfer') ? 'sdTransfer' : 'setup';
const sdTransferPilotFromUrl = new URLSearchParams(location.search).get('sd_transfer');
if(sdTransferPilotFromUrl) window.sdTransferPilotId=sdTransferPilotFromUrl;
let detailFlightId = null;
let pendingTakeoffId = null;
let sdTransferMode = null;
const clientId=localStorage.getItem('telem2_client_id')||((typeof crypto!=='undefined' && crypto.randomUUID&&crypto.randomUUID())||`client-${Date.now()}-${Math.random().toString(36).slice(2)}`);localStorage.setItem('telem2_client_id',clientId);
const adminName=localStorage.getItem('telem2_admin_name')||((prompt('Who are you? Enter your name for the shared dashboard:', '')||'Admin').trim()||'Admin');localStorage.setItem('telem2_admin_name',adminName);
function presenceName(){let n=localStorage.getItem('telem2_admin_name');if(!n){n=prompt('Enter your admin name for shared transfer status:',adminName)||adminName;localStorage.setItem('telem2_admin_name',n)}return n}
function transferPresence(flightId){return state.transfer_presence?.[String(flightId)]||null}
function transferBatchKeyForFlight(flightId){const f=state.flights.find(x=>Number(x.id)===Number(flightId));return `${state.session?.id||''}:${f?.pilot_id||flightId}`}
async function setTransferPresence(flightId,action,batchKey){try{await api('/api/transfer-presence',{method:'POST',body:JSON.stringify({flight_id:flightId,action,admin:presenceName(),client_id:clientId,batch_key:batchKey||flightId})});return true}catch(err){if(action==='open')toast(err.message,true);return false}}
setInterval(()=>{const active=Object.entries(state.transfer_presence||{}).filter(([,v])=>v.client_id===clientId);active.forEach(([flightId,v])=>setTransferPresence(flightId,v.mode==='uploading'?'uploading':'open',v.batch_key))},10000);
const uploadQueue=[]; const uploadRetryFiles=new Map(); const uploadActive=new Set();
const $ = s => document.querySelector(s);
const esc = x => String(x ?? '').replace(/[&<>\"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;'}[c]));
const toast = (msg, error=false) => { const el=$('#toast'); el.textContent=msg; el.className='toast'+(error?' error':''); setTimeout(()=>el.className='toast hidden',3500); };
async function api(url, options={}) { const r=await fetch(url,{headers:{'Content-Type':'application/json',...(options.headers||{})},...options}); const d=await r.json().catch(()=>({})); if(!r.ok) throw new Error(d.error||'Request failed'); return d; }
function activeFlights(){ return state.flights.filter(f=>['planned','ready','flying','transfer'].includes(f.status)); }
function repNumber(f){ return Number(String(f.rep||'REP-99').replace('REP-',''))||99; }
function repGroup(f){ return `${f.pilot_id}|${f.scenario_id}|${f.mode}`; }
function isSuccessful(f){ return f.status==='completed'&&(f.result==='success'||f.result==='needs_sd_transfer'); }
function isCurrentRep(f){ const same=state.flights.filter(x=>repGroup(x)===repGroup(f)); const repNo=repNumber(f); if(f.mode==='DYN'){const calm=state.flights.filter(x=>x.pilot_id===f.pilot_id&&x.scenario_id===f.scenario_id&&x.mode==='CALM');if(calm.filter(isSuccessful).length<4)return false;} if(repNo>1){const previous=same.find(x=>repNumber(x)===repNo-1);if(!previous||!isSuccessful(previous))return false;} const current=same.filter(x=>!isSuccessful(x)).sort((a,b)=>repNumber(a)-repNumber(b))[0]; return !!current&&current.id===f.id; }
function pilotTag(tag){ return `<span class="tag ${tag==='sd card'?'sd':''}">${esc(tag)}</span>`; }
function pilotDisplay(id){ const p=state.pilots.find(x=>x.pilot_id===id); return `${esc(id||'—')}${p?` · ${esc(p.name)}`:''}`; }
function sessionPilots(){ return state.session ? state.pilots.filter(p=>state.participants.includes(p.pilot_id)) : []; }
function pilotLiveStatus(id){ const f=state.flights.find(x=>x.pilot_id===id&&['flying','transfer'].includes(x.status)); return f?.status||null; }
function transferBatchSize(tag){ return tag==='sd card'?4:2; }
function transferAlerts(tag){ const ids=new Set(state.pilots.filter(p=>p.tag===tag).map(p=>p.pilot_id)); return [...ids].flatMap(pilotId=>{const pilot=state.pilots.find(p=>p.pilot_id===pilotId);const batch=transferBatchSize(pilot?.tag);return ['CALM','DYN'].flatMap(mode=>{const pending=state.flights.filter(f=>f.pilot_id===pilotId&&f.mode===mode&&f.status==='completed'&&f.result==='needs_sd_transfer'&&!f.sd_transfer_ack).sort((a,b)=>a.id-b.id);return pending.length>=batch?pending.slice(0,batch):[];});}); }
function sdTransferAlerts(){ return transferAlerts('sd card'); }
function flightCard(f){ const pending=f.flight_id.startsWith('PENDING-'); const presence=transferPresence(f.id); const color=f.status==='flying'?'yellow':f.status==='transfer'?'purple':f.status==='completed'?'success':f.status==='failed'?'failure':f.status==='ready'?'green':''; const transfer=f.status==='transfer'?`<div class="transfer-tools"><button data-action="open-flight" data-id="${f.id}">Open ${esc(f.pilot_id)}</button></div>`:''; return `<div class="flight-card ${color}"><div class="id">${pending?'PENDING':esc(f.flight_id)} <span class="queue-pilot">${pilotDisplay(f.pilot_id)}</span></div><div class="meta"><span class="queue-rep">${esc(f.rep)}</span> · ${esc(f.mode)}</div>${presence?`<div class="transfer-presence ${presence.mode==='uploading'?'uploading':''}">◉ ${esc(presence.admin)} · ${presence.mode==='uploading'?'uploading files':'open'}</div>`:''}<div class="actions">${['completed','failed'].includes(f.status)?'':[['ready','Ready'],['flying','Airborne'],['transfer','Transfer']].map(([st,label])=>`<button data-action="status" data-id="${f.id}" data-status="${st}">${label}</button>`).join('')}</div>${transfer}</div>`; }
function lane(title, status, extra=''){ let fs=state.flights.filter(f=>(f.status===status||extra.includes(f.status))&&(!['planned','ready','flying','transfer'].includes(f.status)||isCurrentRep(f))); if(status==='completed')fs=fs.sort((a,b)=>String(b.flight_id).localeCompare(String(a.flight_id))); return `<div class="lane"><h4>${title}<span>${fs.length}</span></h4>${fs.length?fs.map(flightCard).join(''):'<div class="subtle">No flights</div>'}</div>`; }
function sessionElapsedMs(){const s=state.session||{};return Number(s.timer_elapsed||0)+(s.timer_running&&s.timer_started_at?Math.max(0,Date.now()-Date.parse(s.timer_started_at)):0)}
function formatDuration(ms){const total=Math.floor(ms/1000),h=Math.floor(total/3600),m=Math.floor(total%3600/60),sec=total%60;return [h,m,sec].map((x,i)=>i===0?String(x).padStart(2,'0'):String(x).padStart(2,'0')).join(':')}
function renderSessionTimer(){const s=state.session||{};const controls=currentView==='remove'?`<div class="timer-actions"><button data-action="session-timer" data-timer-action="start" ${s.timer_running?'disabled':''}>Start</button><button data-action="session-timer" data-timer-action="stop" ${s.timer_running?'':'disabled'}>Stop</button><button class="ghost" data-action="session-timer" data-timer-action="reset">Reset</button></div>`:'';return `<div class="session-timer"><div><span class="eyebrow">SESSION TIMER</span><strong id="sessionTimerValue">${formatDuration(sessionElapsedMs())}</strong></div>${controls}</div>`}
let sessionTimerTicker=setInterval(()=>{const el=$('#sessionTimerValue');if(el)el.textContent=formatDuration(sessionElapsedMs())},1000);
function renderLive(){ const total=state.flights.length, done=state.flights.filter(f=>['completed','failed'].includes(f.status)).length, flying=state.flights.filter(f=>f.status==='flying').length, participating=sessionPilots(), blocked=participating.filter(p=>!p.active).length; $('#liveView').innerHTML=`<div class="hero"><div><div class="eyebrow">${state.session?`SESSION ${esc(state.session.session_no)} · ${esc(state.session.date)}`:'NO ACTIVE SESSION'}</div><h2>${state.session?esc(state.session.notes||'Flight operations ready'):'Create a session to begin'}</h2><p>One shared view for pilots, admins, and the transfer queue.</p></div><div class="sd-alerts">${[['regular','FILE TRANSFER NEEDED','regular-alert'],['sd card','SD CARD TRANSFER NEEDED','sd-alert']].map(([tag,title,cls])=>{const list=transferAlerts(tag);return list.length?`<div class="sd-alert ${cls}"><b>${title}</b><div class="sd-alert-list">${[...new Set(list.map(f=>f.pilot_id))].map(id=>`<div class="sd-alert-person"><span>${pilotDisplay(id)}</span><button class="sd-ack" data-action="sd-upload" data-pilot="${esc(id)}" data-mode="${esc(list.find(f=>f.pilot_id===id)?.mode||'CALM')}">Upload</button></div>`).join('')}</div></div>`:''}).join('')}</div><div class="hero-stat"><strong>${done}/${total}</strong><span>flights closed</span></div></div><div class="metrics"><div class="metric"><label>Flying now</label><strong>${flying}</strong><small>live operations</small></div><div class="metric"><label>Next / ready</label><strong>${state.flights.filter(f=>['planned','ready'].includes(f.status)&&isCurrentRep(f)).length}</strong><small>queue</small></div><div class="metric"><label>Transfer lanes</label><strong>${state.flights.filter(f=>f.status==='transfer'&&isCurrentRep(f)).length}</strong><small>admin work</small></div><div class="metric"><label>Blocked pilots</label><strong>${blocked}</strong><small>technical hold</small></div></div><div class="dashboard-grid"><div class="panel"><div class="panel-title"><h3>Flight queue</h3><span>tap a status to update all screens</span></div><div class="lanes">${lane('Flying now','flying')}${lane('Next / ready','ready','planned')}${lane('Transfer in progress','transfer')}${lane('Completed','completed')}${lane('Failed','failed')}</div></div><div class="panel"><div class="panel-title"><h3>Pilot availability</h3><span>${participating.length} participating</span></div><div class="pilot-list">${participating.length?participating.map(p=>`<div class="pilot-row ${pilotLiveStatus(p.pilot_id)==='flying'||pilotLiveStatus(p.pilot_id)==='transfer'?'busy-row':'ready-row'}"><div class="pilot-main"><div class="avatar">${esc(p.pilot_id.replace('PILOT-',''))}</div><div><strong>${esc(p.name)}</strong><div class="pilot-id">${esc(p.pilot_id)}</div></div></div><div class="pilot-state ${pilotLiveStatus(p.pilot_id)==='flying'||pilotLiveStatus(p.pilot_id)==='transfer'?'busy':'ready'}">${pilotTag(p.tag)} <span>● ${pilotLiveStatus(p.pilot_id)==='flying'?'airborne':pilotLiveStatus(p.pilot_id)==='transfer'?'transfer':p.active?'ready':'not ready'}</span></div></div>`).join(''):'<div class="empty">Add pilots in Setup.</div>'}</div></div></div>`; }
function renderSetup(){ const s=state.session||{}; $('#setupView').innerHTML=`<div class="setup-grid"><div class="form-card"><h3>Today’s session</h3><form id="sessionForm"><div class="form-row"><div class="field"><label>Session number</label><input name="session_no" placeholder="e.g. 4" value="${esc(s.session_no||'')}" required></div><div class="field"><label>Date</label><input type="date" name="date" value="${esc(s.date||new Date().toISOString().slice(0,10))}" required></div></div><div class="field"><label>Session notes <span class="subtle">optional</span></label><textarea name="notes" placeholder="Weather, location, team notes…">${esc(s.notes||'')}</textarea></div><div class="form-actions"><button class="primary">${s?'Save new session':'Start session'}</button></div></form></div><div class="form-card"><h3>Register pilot</h3><form id="pilotForm"><div class="field"><label>Pilot ID · permanent</label><input name="pilot_id" placeholder="PILOT-001" required></div><div class="field"><label>Name</label><input name="name" placeholder="Name shown in the dashboard" required></div><div class="field"><label>Pilot tag</label><select name="tag"><option value="regular">regular</option><option value="sd card">sd card</option></select></div><div class="form-actions"><button class="primary">Add / update pilot</button></div></form></div></div><div class="panel section-spacer"><div class="panel-title"><h3>Active pilots</h3><span>IDs never change names</span></div>${state.pilots.length?state.pilots.map(p=>`<div class="pilot-row"><div class="pilot-main"><div class="avatar">${esc(p.pilot_id.replace('PILOT-',''))}</div><div><strong>${esc(p.name)}</strong><div class="pilot-id">${esc(p.pilot_id)}</div></div></div><div class="pilot-row-actions">${pilotTag(p.tag)}<button class="small-btn" type="button" data-action="edit-pilot" data-pilot-id="${esc(p.pilot_id)}" data-pilot-name="${esc(p.name)}" data-pilot-tag="${esc(p.tag)}">Edit</button></div></div>`).join(''):'<div class="empty">No pilots registered for this installation yet.</div>'}</div>`;
 $('#sessionForm').onsubmit=async e=>{e.preventDefault();try{const body=Object.fromEntries(new FormData(e.currentTarget)); await api('/api/session',{method:'POST',body:JSON.stringify(body)});toast('Session started');await load()}catch(err){toast(err.message,true)}};
 renderSessionArchive(); }
function renderSessionArchive(){ const rows=state.sessions||[]; const html=`<div class="panel section-spacer"><div class="panel-title"><h3>All sessions</h3><span>${rows.length} recorded</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Session</th><th>Date</th><th>Status</th><th>Notes</th></tr></thead><tbody>${rows.length?rows.map(x=>`<tr><td><button class="small-btn" data-action="session" data-session-id="${x.id}"><b>${esc(x.session_no)}</b></button>${x.id===state.session?.id?'<span class="tag"> active</span>':''}</td><td>${esc(x.date)}</td><td>${esc(x.status)}</td><td>${esc(x.notes||'—')}</td></tr>`).join(''):'<tr><td colspan="4"><div class="empty">No sessions recorded yet.</div></td></tr>'}</tbody></table></div></div>`; $('#setupView').insertAdjacentHTML('beforeend',html); }
function renderPlanning(){ $('#planningView').innerHTML=`<div class="panel"><div class="panel-title"><h3>Session participants</h3><span>Select pilots for this session</span></div><form id="participantsForm" class="participant-list">${state.pilots.map(p=>`<label class="participant-item"><input type="checkbox" name="pilot_ids" value="${p.pilot_id}" ${state.participants.includes(p.pilot_id)?'checked':''}>${esc(p.pilot_id)} · ${esc(p.name)}</label>`).join('')}<button class="primary">Save participants</button></form></div><div class="panel section-spacer"><div class="panel-title"><h3>Scenarios</h3><span>${state.scenarios.length} configured</span></div><div class="planning-list">${state.scenarios.length?state.scenarios.map(s=>`<span class="scenario-pill">${esc(s.name)}</span>`).join(''):'<div class="empty">No scenarios configured yet.</div>'}</div><form id="scenarioForm" class="inline-form"><div class="field"><label>Create scenario from list</label><select name="name" required><option value="Linijinis skrydis A–B–A">SC-01 · Linijinis skrydis A–B–A</option><option value="Kvadratas">SC-02 · Kvadratas</option><option value="Ovalas">SC-03 · Ovalas</option><option value="Freestyle / trys laiptai">SC-04 · Freestyle / trys laiptai</option><option value="Slalomas">SC-05 · Slalomas</option><option value="Aštuoniukė">SC-06 · Aštuoniukė</option></select></div><button class="primary">Add scenario</button></form><div class="series-generator"><h4>Generate pending flights</h4><p class="subtle">Select one scenario. The selected session participants each receive 4 CALM and 4 DYN pending flights.</p><form id="seriesForm"><div class="form-row"><div class="field"><label>Scenario</label><select name="scenario_id" required>${state.scenarios.map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('')}</select></div><div class="field"><label>Participating pilots</label><div class="participant-list">${state.pilots.map(p=>`<label class="participant-item"><input type="checkbox" name="pilot_ids" value="${p.pilot_id}" ${state.participants.includes(p.pilot_id)?'checked':''}>${esc(p.pilot_id)} · ${esc(p.name)}</label>`).join('')}</div></div></div><button class="primary">Generate 8 pending flights</button></form></div></div><div class="panel section-spacer"><div class="panel-title"><h3>Pending flights</h3><span>${state.flights.filter(f=>f.flight_id.startsWith('PENDING-')).length} awaiting files</span></div><div class="planning-list">${state.flights.filter(f=>f.flight_id.startsWith('PENDING-')).length?state.flights.filter(f=>f.flight_id.startsWith('PENDING-')).map(f=>`<div class="round-card"><div class="round-head"><h3>Pending · ${esc(f.pilot_id)}</h3><button class="small-btn" data-action="open-flight" data-id="${f.id}">Open flight</button></div><div class="subtle">${esc(f.scenario_name||'Scenario')} · ${esc(f.mode)} · ${esc(f.rep)}</div></div>`).join(''):'<div class="empty">No pending flights.</div>'}</div></div>`;
 $('#participantsForm').onsubmit=async e=>{e.preventDefault();try{const ids=[...new FormData(e.currentTarget).getAll('pilot_ids')];await api('/api/session/'+state.session.id+'/participants',{method:'PUT',body:JSON.stringify({pilot_ids:ids})});toast('Session participants saved');await load()}catch(err){toast(err.message,true)}};
 $('#scenarioForm').onsubmit=async e=>{e.preventDefault();try{await api('/api/scenarios',{method:'POST',body:JSON.stringify({...Object.fromEntries(new FormData(e.currentTarget)),session_id:state.session?.id})});toast('Scenario added');await load()}catch(err){toast(err.message,true)}};
 $('#seriesForm').onsubmit=async e=>{e.preventDefault();try{const form=new FormData(e.currentTarget);const d=await api('/api/flights',{method:'POST',body:JSON.stringify({...Object.fromEntries(form),pilot_ids:[...form.getAll('pilot_ids')],session_id:state.session?.id})});toast(`${d.count} pending flights created`);await load()}catch(err){toast(err.message,true)}}; }
function renderHistory(){ $('#historyView').innerHTML=`<div class="panel"><div class="panel-title"><h3>Flight history</h3><span>structured record · Flight ID is permanent</span></div><div class="searchbar"><input id="historySearch" placeholder="Search Flight ID, pilot, scenario, UAV, battery…"><select id="historyStatus"><option value="">All statuses</option><option>completed</option><option>failed</option><option>transfer</option><option>flying</option><option>planned</option></select></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Flight ID</th><th>Pilot</th><th>UAV</th><th>Battery</th><th>Scenario</th><th>Mode</th><th>W</th><th>REP</th><th>Result</th><th>Notes</th></tr></thead><tbody id="historyBody"></tbody></table></div></div>`; const draw=()=>{const q=($('#historySearch').value||'').toLowerCase(), st=$('#historyStatus').value; const rows=state.flights.filter(f=>(!st||f.status===st)&&(!q||JSON.stringify(f).toLowerCase().includes(q))).sort((a,b)=>{const ap=a.flight_id.startsWith('FL-')?Number(a.flight_id.slice(3)): -1;const bp=b.flight_id.startsWith('FL-')?Number(b.flight_id.slice(3)): -1;return bp-ap||b.id-a.id});$('#historyBody').innerHTML=rows.length?rows.map(f=>`<tr><td><b>${esc(f.flight_id)}</b></td><td>${esc(f.pilot_id)}<br><span class="subtle">${esc(f.pilot_name||'')}</span></td><td>${esc(f.uav_id)}</td><td>${esc(f.battery_id)}</td><td>${esc(f.scenario_code)}</td><td>${esc(f.mode)}</td><td>${esc(f.weather)}</td><td>${esc(f.rep)}</td><td>${esc(f.result || (f.status==='completed'?'success':f.status==='failed'?'failed':f.status||'—'))}</td><td>${esc(f.notes||'—')}</td></tr>`).join(''):'<tr><td colspan="10"><div class="empty">No matching flights.</div></td></tr>'}; $('#historySearch').oninput=draw;$('#historyStatus').onchange=draw;draw(); }
function renderAdmin(){ $('#adminView').innerHTML=`<div class="panel"><div class="panel-title"><h3>Session administration</h3><span>Delete a session and all of its rounds, flights, notes, and uploaded files.</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Session</th><th>Date</th><th>Status</th><th>Notes</th><th></th></tr></thead><tbody>${(state.sessions||[]).length?state.sessions.map(x=>`<tr><td><b>${esc(x.session_no)}</b></td><td>${esc(x.date)}</td><td>${esc(x.status)}</td><td>${esc(x.notes||'—')}</td><td><button class="danger" data-action="delete-session" data-session-id="${x.id}">Delete</button></td></tr>`).join(''):'<tr><td colspan="5"><div class="empty">No sessions.</div></td></tr>'}</tbody></table></div></div>`; }
function renderFlightDetail(){ const f=state.flights.find(x=>x.id===detailFlightId); if(!f){$('#flightDetailView').innerHTML='<div class="empty">Flight not found.</div>';return} const files=state.files.filter(x=>x.flight_id===f.flight_id); const hasTelemetry=files.some(x=>x.kind==='telemetry'); const hasGoggles=files.some(x=>x.kind==='goggles'); const batteryReady=!!String(f.battery_id||'').trim(); const pilotTagValue=f.pilot_tag||state.pilots.find(x=>x.pilot_id===f.pilot_id)?.tag||'regular'; const batchSize=transferBatchSize(pilotTagValue); const batchLocked=state.flights.filter(x=>x.pilot_id===f.pilot_id&&isSuccessful(x)).length<batchSize; $('#flightDetailView').innerHTML=`<div class="detail-head"><button class="ghost" data-action="back-flight">← Back to LiveView</button><div><div class="eyebrow">${esc(f.pilot_id)} · ${esc(f.rep)}</div><h2>${f.flight_id.startsWith('PENDING-')?'Pending flight':esc(f.flight_id)}</h2></div></div><div class="panel battery-entry"><div class="battery-entry-head"><label for="detailBattery">Battery number</label><button class="small-btn" data-action="edit-battery" data-id="${f.id}">Edit battery</button></div><input id="detailBattery" value="${esc(f.battery_id||'').replace(/^BAT-/i,'')}" placeholder="Enter battery number" inputmode="numeric" readonly data-battery-flight="${f.id}"><span>Read-only after entry. Press Edit battery to change it.</span></div><div class="panel detail-meta"><b>Flight information</b><span>Pilot ${esc(f.pilot_id)} · Battery ${esc(f.battery_id||'pending')} · ${esc(f.mode)} · ${esc(f.weather)} · ${esc(f.rep)}</span><span>Status: ${esc(f.status)}</span><div class="detail-result-actions"><button class="success-button" ${batteryReady?'':'disabled'} data-action="status" data-id="${f.id}" data-status="completed" data-result="${['sd card','regular'].includes(pilotTagValue)&&!hasTelemetry&&!hasGoggles?'needs_sd_transfer':'success'}">${!batteryReady?'Enter battery number':(['sd card','regular'].includes(pilotTagValue)&&!hasTelemetry&&!hasGoggles?'Complete · Needs file transfer':'Complete')}</button><button class="fail-button" data-action="status" data-id="${f.id}" data-status="failed" data-result="failed">Fail</button></div></div>`; }
function renderAudit(){const rows=state.events||[];$('#auditView').innerHTML=`<div class="panel"><div class="panel-title"><h3>Audit log</h3><span>${rows.length} recent events</span></div><div class="table-wrap"><table class="data-table audit-table"><thead><tr><th>Time</th><th>Action</th><th>Flight</th><th>Details</th></tr></thead><tbody>${rows.length?rows.map(e=>`<tr><td>${esc(new Date(e.created_at).toLocaleString('lt-LT',{timeZone:'Europe/Vilnius',dateStyle:'short',timeStyle:'medium'}))}</td><td><b>${esc(e.event_type)}</b></td><td>${esc(e.event_flight_id||e.flight_id||'—')}</td><td>${esc(e.details||'—')}</td></tr>`).join(''):'<tr><td colspan="4"><div class="empty">No audit events for this session yet.</div></td></tr>'}</tbody></table></div></div>`;}
function renderRemove(){ const rows=state.flights||[]; $('#removeView').innerHTML=`<div class="panel"><div class="panel-title"><h3>Remove flights</h3><span>Deleted flights and their uploaded files cannot be restored.</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Flight</th><th>Pilot</th><th>Scenario</th><th>Battery</th><th>Result</th><th></th></tr></thead><tbody>${rows.length?rows.map(f=>`<tr><td><b>${f.flight_id.startsWith('PENDING-')?'PENDING':esc(f.flight_id)}</b></td><td>${esc(f.pilot_id||'—')}</td><td>${esc(f.scenario_name||f.scenario_code||'—')}</td><td>${esc(f.battery_id||'—')}</td><td>${esc(f.result||f.status||'—')}</td><td><button class="danger" data-action="delete-flight" data-flight-id="${f.id}">Remove</button></td></tr>`).join(''):'<tr><td colspan="6"><div class="empty">No flights in this session.</div></td></tr>'}</tbody></table></div></div>`; }
function renderSdTransfer(){ const pilotId=window.sdTransferPilotId; const pilot=state.pilots.find(p=>p.pilot_id===pilotId); const mode=sdTransferMode||'CALM'; const flights=state.flights.filter(f=>f.pilot_id===pilotId&&f.mode===mode&&f.status==='completed'&&f.result==='needs_sd_transfer'&&!f.sd_transfer_ack).slice(0,transferBatchSize(pilot?.tag)); const slot=(f,kind,label)=>{const saved=state.files.find(x=>x.flight_id===f.flight_id&&x.kind===kind);const ok=!!saved;const presence=transferPresence(f.id);return `<div class="sd-slot"><b>${label}</b>${presence?`<span class="transfer-presence ${presence.mode==='uploading'?'uploading':''}">◉ ${esc(presence.admin)} · ${presence.mode==='uploading'?'uploading':'open'}</span>`:''}<span>${esc(f.mode)} · ${esc(f.rep)}</span><label class="sd-file ${ok?'uploaded':''}"><input data-upload-slot="${f.id}:${kind}" type="file" data-sd-flight="${f.id}" data-sd-kind="${kind}" ${ok?'disabled':''}><strong>${ok?esc(saved.original_name):'Upload file'}</strong><span class="upload-status" data-upload-status="${f.id}:${kind}">${ok?'Uploaded':''}</span><progress class="upload-progress" data-upload-progress="${f.id}:${kind}" value="0" max="100"></progress></label></div>`}; const all=flights.length===transferBatchSize(pilot?.tag)&&flights.every(f=>state.files.some(x=>x.flight_id===f.flight_id&&x.kind==='telemetry')&&state.files.some(x=>x.flight_id===f.flight_id&&x.kind==='goggles')); $('#sdTransferView').innerHTML=`<div class="detail-head"><button class="ghost" data-action="back-sd">← Back to LiveView</button><div><div class="eyebrow">${esc(pilotId||'SD CARD')} · FILE TRANSFER</div><h2>SD-card transfer · ${esc(pilot?.name||'')}</h2></div></div><div class="hero"><div><h2>Upload completed flights</h2><p>Upload one blackbox file and one goggles video for each flight.</p></div><div class="hero-stat"><strong>${all?'READY':'${flights.length} × 2'}</strong><span>${all?'all files uploaded':'files required'}</span></div></div><div class="sd-batch-grid"><div><h3>Blackbox telemetry</h3>${flights.map(f=>slot(f,'telemetry','Blackbox '+f.rep)).join('')}</div><div><h3>Goggles video</h3>${flights.map(f=>slot(f,'goggles','Video '+f.rep)).join('')}</div></div><button class="sd-confirm" data-action="confirm-sd" data-pilot="${esc(pilotId||'')}" data-mode="${esc(mode)}" ${all?'':'disabled'}>CONFIRM · ASSIGN FLIGHT NUMBERS</button>`; }
function openTakeoffDialog(id){pendingTakeoffId=Number(id);const f=state.flights.find(x=>x.id===pendingTakeoffId);const lastBattery=state.flights.filter(x=>x.pilot_id===f?.pilot_id&&String(x.battery_id||'').trim()).sort((a,b)=>b.id-a.id)[0]?.battery_id||'Not recorded';$('#takeoffBatteryFlight').textContent=`${f?.flight_id||'Flight'} · ${pilotDisplay(f?.pilot_id)}`;$('#takeoffBatteryLast').textContent=`Last battery: ${lastBattery}`;$('#takeoffBatteryInput').value=f?.battery_id?.replace(/^BAT-/i,'')||'';$('#takeoffBatteryModal').classList.remove('hidden');setTimeout(()=>$('#takeoffBatteryInput').focus(),50);}
async function confirmTakeoffDialog(){const value=$('#takeoffBatteryInput').value.trim();if(!value){toast('Enter the battery number first',true);return}try{const f=state.flights.find(x=>x.id===pendingTakeoffId);await api('/api/flights/'+pendingTakeoffId,{method:'PATCH',body:JSON.stringify({status:'flying',battery_id:`BAT-${value.replace(/^BAT-/i,'')}`})});pendingTakeoffId=null;$('#takeoffBatteryModal').classList.add('hidden');currentView=window.matchMedia('(max-width:650px)').matches?'takeoff':'live';await load();showTakeoffNotification(f)}catch(err){toast(err.message,true)}}
function renderTakeoff(){ const current=state.flights.filter(f=>f.status==='flying'&&isCurrentRep(f)); const next=state.flights.filter(f=>(f.status==='ready'||f.status==='planned')&&isCurrentRep(f)).sort((a,b)=>a.id-b.id); const lastBattery=pilotId=>state.flights.filter(x=>x.pilot_id===pilotId&&String(x.battery_id||'').trim()).sort((a,b)=>b.id-a.id)[0]?.battery_id||'Not recorded'; const card=(f,queueNumber)=>`<div class="takeoff-card ${f.status==='flying'?'airborne':''}"><div>${queueNumber?`<div class="takeoff-queue-number">${queueNumber}</div>`:''}<div class="eyebrow">${f.status==='flying'?'TAKING OFF NOW':'NEXT UP'}</div><h3>${pilotDisplay(f.pilot_id)}</h3><p class="takeoff-last-battery">Last battery: <b>${esc(lastBattery(f.pilot_id))}</b></p><p class="takeoff-flight-line"><b>${f.flight_id.startsWith('PENDING-')?'FL —':esc(f.flight_id)}</b> · <b>${esc(f.scenario_code||'SC-—')}</b> · <b>${esc(f.battery_id||'BAT-—')}</b> · <b>${esc(f.mode)}</b></p></div>${f.status==='ready'||f.status==='planned'?`<button class="takeoff-button" data-action="takeoff" data-id="${f.id}">Took off</button>`:'<span class="airborne-label">AIRBORNE</span>'}</div>`; $('#takeoffView').innerHTML=`<div class="hero takeoff-hero"><div><div class="eyebrow">TAKEOFF DESK</div><h2>Who is taking off?</h2><p>Mark a pilot as airborne when they leave the ground.</p></div><div class="hero-stat"><strong>${current.length}</strong><span>airborne now</span></div></div><div class="panel"><div class="panel-title"><h3>Taking off now</h3><span>${current.length} pilots airborne</span></div>${current.length?current.map(card).join(''):'<div class="empty">No pilot is airborne right now.</div>'}</div><div class="panel section-spacer"><div class="panel-title"><h3>Next up</h3><span>${next.length} ready in queue</span></div>${next.length?next.map((f,i)=>card(f,i+1)).join(''):'<div class="empty">No next flight is ready.</div>'}</div>`; document.querySelectorAll('#takeoffView [data-action=\"takeoff\"]').forEach(button=>button.onclick=e=>{e.stopPropagation();openTakeoffDialog(button.dataset.id)});document.querySelector('#takeoffBatteryModal [data-action=\"confirm-takeoff\"]').onclick=e=>{e.stopPropagation();confirmTakeoffDialog()};document.querySelector('#takeoffBatteryModal [data-action=\"cancel-takeoff\"]').onclick=e=>{e.stopPropagation();pendingTakeoffId=null;$('#takeoffBatteryModal').classList.add('hidden')}; }
function renderPending(){ const rows=state.flights.filter(f=>f.flight_id.startsWith('PENDING-')); $('#pendingView').innerHTML=`<div class="panel"><div class="panel-title"><h3>Pending flights</h3><span>${rows.length} awaiting files</span></div><div class="planning-list">${rows.length?rows.map(f=>`<div class="round-card"><div class="round-head"><h3>Pending · ${pilotDisplay(f.pilot_id)}</h3><button class="small-btn" data-action="open-flight" data-id="${f.id}">Open flight</button></div><div class="subtle">${esc(f.scenario_name||'Scenario')} · ${esc(f.mode)} · ${esc(f.rep)} · ${esc(f.battery_id||'BAT pending')}</div></div>`).join(''):'<div class="empty">No pending flights.</div>'}</div></div>`; }
function renderProgressMatrix(){ const sessionFlights=state.flights.filter(f=>!state.session?.id||f.session_id===state.session.id); const codes=[...new Set(sessionFlights.map(f=>f.scenario_code).filter(Boolean))].sort(); const completed=f=>f.status==='completed'||f.result==='success'||f.result==='needs_sd_transfer'; const assigned=(pilot,code)=>sessionFlights.some(f=>f.pilot_id===pilot&&f.scenario_code===code); const count=(pilot,code,mode)=>sessionFlights.filter(f=>completed(f)&&f.pilot_id===pilot&&f.scenario_code===code&&f.mode===mode).length; const pilotIds=[...new Set(sessionFlights.map(f=>f.pilot_id).filter(Boolean))]; const pilots=state.pilots.filter(p=>pilotIds.includes(p.pilot_id)); const rows=pilots.map(p=>`<tr><td><b>${esc(p.pilot_id)}</b></td><td>${esc(p.name)}</td><td><b>${sessionFlights.filter(f=>f.pilot_id===p.pilot_id).length}</b></td>${codes.map(code=>{const has=assigned(p.pilot_id,code);return `<td>${has?count(p.pilot_id,code,'CALM'):''}</td><td>${has?count(p.pilot_id,code,'DYN'):''}</td>`}).join('')}</tr>`).join(''); const colspan=3+codes.length*2; $('#liveView').insertAdjacentHTML('beforeend',`<div class="panel progress-panel section-spacer"><div class="panel-title"><h3>Session scenario progress</h3><span>selected scenarios · completed flights</span></div><div class="matrix-wrap"><table class="progress-table"><thead><tr><th colspan="3">Pilot</th>${codes.map(code=>`<th colspan="2">${esc(code)}</th>`).join('')}</tr><tr><th>PILOT ID</th><th>Name</th><th>Target</th>${codes.map(()=>'<th>CALM</th><th>DYN</th>').join('')}</tr></thead><tbody>${rows||`<tr><td colspan="${colspan}"><div class="empty">No assigned scenario flights yet.</div></td></tr>`}</tbody></table></div></div>`); }
function userColor(name){let n=0;for(const c of String(name||''))n=(n*31+c.charCodeAt(0))>>>0;return n%6}
function renderDroneStatus(){const root=$('#droneStatus');if(!root)return;const devices=state.drone_devices||[];const labels={disconnected:'disconnected',connecting:'connecting…',verified:'Betaflight connected',mass_storage:'mass-storage ready',error:'connection error'};root.className='drone-status-list';root.innerHTML=devices.length?devices.map(d=>{const parts=[];if(d.operator)parts.push('By: '+d.operator);if(d.port)parts.push('Port: '+d.port);if(d.updated_at)parts.push('Updated: '+new Date(d.updated_at).toLocaleTimeString('lt-LT'));return `<div class="drone-status drone-status-${d.state||'disconnected'}"><span class="drone-status-dot"></span><div><b>Drone: ${labels[d.state]||d.state||'disconnected'}</b><small>${esc(d.message||'No status message')}</small><em class="drone-status-meta">${esc(parts.join(' · '))}</em></div></div>`}).join(''):'<div class="drone-status drone-status-disconnected"><span class="drone-status-dot"></span><div><b>Drone: disconnected</b><small>No flight controller connected</small><em class="drone-status-meta"></em></div></div>';}
function renderConnectedUsers(){const root=$('#connectedUsers');if(!root)return;const users=state.connected_users||[];root.querySelector('.connected-users-list').innerHTML=users.length?users.map(u=>{const name=String(u.name||'Admin');return `<div class="connected-user" title="${esc(name)}"><i class="user-avatar user-color-${userColor(name)}">${esc(name.trim().charAt(0).toUpperCase()||'?')}</i><span>${esc(name)}</span></div>`}).join(''):'<div class="connected-empty">No other users</div>';}

