function captureEditFocus(){const el=document.activeElement;if(!el||!el.matches('input,textarea,select'))return null;return {id:el.id,name:el.name,value:el.value,start:typeof el.selectionStart==='number'?el.selectionStart:null,end:typeof el.selectionEnd==='number'?el.selectionEnd:null};}
function restoreEditFocus(snapshot){if(!snapshot)return;const el=(snapshot.id&&document.getElementById(snapshot.id))||(snapshot.name&&document.querySelector(`[name=\"${CSS.escape(snapshot.name)}\"]`));if(!el)return;if((el.tagName==='INPUT'||el.tagName==='TEXTAREA')&&el.value!==snapshot.value)el.value=snapshot.value;el.focus({preventScroll:true});if(snapshot.start!==null&&typeof el.setSelectionRange==='function')el.setSelectionRange(Math.min(snapshot.start,el.value.length),Math.min(snapshot.end,el.value.length));}
async function load(sessionId=selectedSessionId){ const focus=captureEditFocus(); const query=sessionId?`?session_id=${encodeURIComponent(sessionId)}`:''; state=await api('/api/state'+query); selectedSessionId=state.session?.id||null; const host=$('#hostAddress');if(host)host.textContent=(state.lan_url||location.origin).replace(/^https?:\/\//,''); if(focus&&isEditingControl()){deferredLiveRefresh=true;return} render(); restoreEditFocus(focus); }
document.addEventListener('submit',async e=>{const form=e.target.closest('#pilotForm');if(!form)return;e.preventDefault();const values=Object.fromEntries(new FormData(form));values.pilot_id=String(values.pilot_id||'').trim().toUpperCase();values.name=String(values.name||'').trim();values.tag=String(values.tag||'').trim().toLowerCase();const button=form.querySelector('button[type=submit],button:not([type])');if(button)button.disabled=true;try{await api('/api/pilots',{method:'POST',body:JSON.stringify(values)});toast(`${values.pilot_id} saved`);form.reset();if(state.pilots&&!state.pilots.some(p=>p.pilot_id===values.pilot_id)){state.pilots.push({pilot_id:values.pilot_id,name:values.name,tag:values.tag,active:1});}renderSetup()}catch(err){toast(err.message,true)}finally{if(button)button.disabled=false}});
document.addEventListener('click',async e=>{const takeoffButton=e.target.closest('[data-action="takeoff"]');if(takeoffButton)e.preventDefault();const editPilot=e.target.closest('[data-action="edit-pilot"]');if(editPilot){const form=$('#pilotForm');if(form){form.elements.pilot_id.value=editPilot.dataset.pilotId;form.elements.pilot_id.readOnly=true;form.elements.name.value=editPilot.dataset.pilotName;form.elements.tag.value=editPilot.dataset.pilotTag;const submit=form.querySelector('button[type=submit],button:not([type])');if(submit)submit.textContent='Update pilot';form.scrollIntoView({behavior:'smooth',block:'center'});toast(`Editing ${editPilot.dataset.pilotId}`);}return;}const retry=e.target.closest('[data-upload-retry]');if(retry){const slot=retry.dataset.uploadRetry,file=uploadRetryFiles.get(slot);if(file){const [flightId,kind]=slot.split(':');setSlotStatus(slot,'Queued…');uploadQueue.push(()=>sendQueuedUpload(flightId,kind,file,slot));runUploadQueue()}return}const uploadSd=e.target.closest('[data-action="sd-upload"]');if(uploadSd){window.sdTransferPilotId=uploadSd.dataset.pilot;sdTransferMode=uploadSd.dataset.mode||'CALM';const batch=state.flights.filter(f=>f.pilot_id===uploadSd.dataset.pilot&&f.mode===sdTransferMode&&f.result==='needs_sd_transfer');const batchKey=`${state.session?.id||''}:${uploadSd.dataset.pilot}`;const opened=await Promise.all(batch.map(f=>setTransferPresence(f.id,'open',batchKey)));if(!opened.every(Boolean))return;window.open(`/?session_id=${encodeURIComponent(state.session?.id||'')}&sd_transfer=${encodeURIComponent(uploadSd.dataset.pilot)}`,'_blank','noopener');return}const backSd=e.target.closest('[data-action="back-sd"]');if(backSd){currentView='live';render();return}const confirmSd=e.target.closest('[data-action="confirm-sd"]');if(confirmSd){try{const d=await api('/api/sd-transfer/'+confirmSd.dataset.pilot+'/confirm',{method:'POST',body:JSON.stringify({session_id:state.session?.id,mode:confirmSd.dataset.mode||sdTransferMode||'CALM'})});toast(`${d.flight_ids.length} flight numbers assigned`);currentView='live';await load()}catch(err){toast(err.message,true)}return}const ack=e.target.closest('[data-action="sd-ack"]');if(ack){if(!confirm('Confirm that the video and FC files for this pilot have been received?'))return;try{await api('/api/flights/'+ack.dataset.id,{method:'PATCH',body:JSON.stringify({sd_transfer_ack:1})});toast('SD transfer acknowledged');await load()}catch(err){toast(err.message,true)}return}const takeoff=e.target.closest('[data-action="takeoff"]');if(takeoff){pendingTakeoffId=Number(takeoff.dataset.id);const f=state.flights.find(x=>x.id===pendingTakeoffId);const lastBattery=state.flights.filter(x=>x.pilot_id===f?.pilot_id&&String(x.battery_id||'').trim()).sort((a,b)=>b.id-a.id)[0]?.battery_id||'Not recorded';$('#takeoffBatteryFlight').textContent=`${pilotDisplay(f?.pilot_id)} · ${f?.scenario_code||'Scenario'} · ${f?.mode||'—'} · ${f?.rep||'—'}`;$('#takeoffBatteryLast').textContent=`Last used battery: ${lastBattery}`;$('#takeoffBatteryInput').value=f?.battery_id?.replace(/^BAT-/i,'')||'';$('#takeoffBatteryModal').classList.remove('hidden');setTimeout(()=>$('#takeoffBatteryInput').focus(),50);return}const cancelTakeoff=e.target.closest('[data-action="cancel-takeoff"]');if(cancelTakeoff){pendingTakeoffId=null;$('#takeoffBatteryModal').classList.add('hidden');return}const confirmTakeoff=e.target.closest('[data-action="confirm-takeoff"]');if(confirmTakeoff){const value=$('#takeoffBatteryInput').value.trim();if(!value){toast('Enter the battery number first',true);return}try{const f=state.flights.find(x=>x.id===pendingTakeoffId);await api('/api/flights/'+pendingTakeoffId,{method:'PATCH',body:JSON.stringify({status:'flying',battery_id:`BAT-${value.replace(/^BAT-/i,'')}`})});pendingTakeoffId=null;$('#takeoffBatteryModal').classList.add('hidden');currentView=window.matchMedia('(max-width:650px)').matches?'takeoff':'live';await load();showTakeoffNotification(f)}catch(err){toast(err.message,true)}return}const editBattery=e.target.closest('[data-action="edit-battery"]');if(editBattery){const input=$('#detailBattery');if(input){input.readOnly=false;input.focus();input.select();editBattery.textContent='Save battery';editBattery.dataset.action='save-battery';}return}const saveBattery=e.target.closest('[data-action="save-battery"]');if(saveBattery){const input=$('#detailBattery');if(input){try{const value=input.value.trim();await api('/api/flights/'+saveBattery.dataset.id,{method:'PATCH',body:JSON.stringify({battery_id:value?`BAT-${value.replace(/^BAT-/i,'')}`:''})});input.readOnly=true;saveBattery.textContent='Edit battery';saveBattery.dataset.action='edit-battery';toast('Battery number saved');await load()}catch(err){toast(err.message,true)}}return}const open=e.target.closest('[data-action="open-flight"]');if(open){detailFlightId=Number(open.dataset.id);currentView='detail';render();return}const backFlight=e.target.closest('[data-action="back-flight"]');if(backFlight){detailFlightId=null;currentView='live';render();return}const back=e.target.closest('#backSessions');if(back){selectedSessionId=null;currentView='setup';await load();return}const removeFlight=e.target.closest('[data-action="delete-flight"]');if(removeFlight){if(!confirm('Remove this flight and all uploaded files?'))return;try{await api('/api/flights/'+removeFlight.dataset.flightId,{method:'DELETE'});toast('Flight removed successfully');if(detailFlightId===Number(removeFlight.dataset.flightId)){detailFlightId=null;currentView='live'}await load()}catch(err){toast(err.message,true)}return}const del=e.target.closest('[data-action="delete-session"]');if(del){if(!confirm('Delete this session and all of its flights and uploaded files?'))return;try{await api('/api/session/'+del.dataset.sessionId,{method:'DELETE'});if(Number(del.dataset.sessionId)===selectedSessionId){selectedSessionId=null;currentView='admin'}toast('Session deleted successfully');await load()}catch(err){toast(err.message,true)}return}const sessionButton=e.target.closest('[data-action="session"]');if(sessionButton){selectedSessionId=Number(sessionButton.dataset.sessionId);currentView='live';await load(selectedSessionId);toast(`Opened session ${state.session.session_no}`);return}const n=e.target.closest('[data-view]');if(n){currentView=n.dataset.view;document.querySelectorAll('.nav-link').forEach(x=>x.classList.remove('active'));n.classList.add('active');document.querySelectorAll('.view').forEach(x=>x.classList.remove('active'));$('#'+n.dataset.view+'View').classList.add('active');$('#pageTitle').textContent=n.textContent.trim();const timerBar=$('#sessionTimerBar');if(timerBar)timerBar.innerHTML=state.session?renderSessionTimer():'';return}const timer=e.target.closest('[data-action="session-timer"]');if(timer){try{await api('/api/session/'+state.session.id,{method:'PATCH',body:JSON.stringify({timer_action:timer.dataset.timerAction})});await load()}catch(err){toast(err.message,true)}return}const a=e.target.closest('[data-action="status"]');if(a){try{const f=state.flights.find(x=>String(x.id)===a.dataset.id);await api('/api/flights/'+a.dataset.id,{method:'PATCH',body:JSON.stringify({status:a.dataset.status,result:a.dataset.result || (a.dataset.status==='completed'?'success':a.dataset.status==='failed'?'failed':undefined)})});toast(`${f.flight_id} → ${a.dataset.status}`);if(a.dataset.status==='completed'){const notice=$('#successExit');notice.classList.remove('hidden');setTimeout(()=>{notice.classList.add('hidden');currentView='live';load()},600)}else await load()}catch(err){toast(err.message,true)}}});
$('#syncBtn').onclick=async()=>{try{const d=await api('/api/sync',{method:'POST',body:'{}'});toast(d.message||'Snapshot synced');}catch(err){toast(err.message,true)}};
let editingControl=false;let deferredLiveRefresh=false;function isEditingControl(){const el=document.activeElement;return !!el&&el.matches('input,textarea,select,[contenteditable=\"true\"]')&&!el.readOnly&&!el.disabled;}document.addEventListener('focusin',e=>{if(e.target.matches('input,textarea,select,[contenteditable=\"true\"]'))editingControl=true});document.addEventListener('focusout',()=>{setTimeout(()=>{editingControl=isEditingControl();if(!editingControl&&deferredLiveRefresh){deferredLiveRefresh=false;load()}},0)});function handleLiveRefresh(){if(currentView==='setup'){return}if(editingControl||isEditingControl()){deferredLiveRefresh=true;return}load();}const es=new EventSource('/api/events');es.onopen=()=>{$('#connectionDot').parentElement.classList.add('online');$('#connectionText').textContent='Live · shared host';$('#offlineOverlay').classList.add('hidden')};es.onmessage=handleLiveRefresh;es.onerror=()=>{$('#connectionDot').parentElement.classList.remove('online');$('#connectionText').textContent='Reconnecting…';$('#offlineOverlay').classList.remove('hidden')};
function showTakeoffNotification(f){const n=document.createElement('div');n.className='takeoff-notification';n.innerHTML=`<b>TAKEOFF</b><strong>${esc(f.pilot_id)}${f.pilot_name?` · ${esc(f.pilot_name)}`:''}</strong><span>${esc(f.scenario_name||f.scenario_code||'Scenario')} · ${esc(f.mode)} · ${esc(f.rep)}</span>`;document.body.appendChild(n);setTimeout(()=>n.remove(),5000);}
function setSlotStatus(slot,text,progress=null){const status=document.querySelector(`[data-upload-status=\"${slot}\"]`);if(status){status.innerHTML=text.startsWith('Upload failed')?`${text} <button class=\"retry-upload\" data-upload-retry=\"${slot}\">Retry</button>`:esc(text)}const bar=document.querySelector(`[data-upload-progress=\"${slot}\"]`);if(bar){bar.hidden=progress===null; if(progress!==null)bar.value=progress;}}
function sendQueuedUpload(flightId,kind,file,slot){return new Promise(resolve=>{setTransferPresence(flightId,'uploading',transferBatchKeyForFlight(flightId));uploadActive.add(slot);setSlotStatus(slot,'Uploading…',0);const xhr=new XMLHttpRequest();xhr.open('POST',`/api/flights/${flightId}/files`);xhr.upload.onprogress=e=>{if(e.lengthComputable)setSlotStatus(slot,`Uploading… ${Math.round(e.loaded/e.total*100)}%`,Math.round(e.loaded/e.total*100))};xhr.onload=()=>{try{const d=JSON.parse(xhr.responseText||'{}');if(xhr.status<200||xhr.status>=300)throw new Error(d.error||'Upload failed');const f=state.flights.find(x=>x.id===Number(flightId));if(f&&d.files)state.files.push(...d.files.map(x=>({...x,flight_id:f.flight_id})));setSlotStatus(slot,'Uploaded');toast('File uploaded');renderSdTransfer()}catch(err){setSlotStatus(slot,'Upload failed · Retry');const status=document.querySelector(`[data-upload-status=\"${slot}\"]`);if(status)status.dataset.retry=slot;toast(err.message,true)}uploadActive.delete(slot);setTransferPresence(flightId,'open',transferBatchKeyForFlight(flightId));resolve()};xhr.onerror=()=>{setSlotStatus(slot,'Upload failed · Retry');uploadActive.delete(slot);setTransferPresence(flightId,'open',transferBatchKeyForFlight(flightId));toast('Upload failed. Retry the slot.',true);resolve()};const form=new FormData();form.append('files',file);form.append('kind',kind);form.append('sd_batch','1');xhr.send(form)});}
function runUploadQueue(){if(uploadQueue.running)return;uploadQueue.running=true;const next=()=>{const job=uploadQueue.shift();if(!job){uploadQueue.running=false;return}job().then(next)};next()}
document.addEventListener('change',async e=>{const sd=e.target.closest('[data-sd-flight]');if(sd&&sd.files.length){const file=sd.files[0];const slot=`${sd.dataset.sdFlight}:${sd.dataset.sdKind}`;uploadRetryFiles.set(slot,file);sd.disabled=true;setSlotStatus(slot,'Queued…');uploadQueue.push(()=>sendQueuedUpload(sd.dataset.sdFlight,sd.dataset.sdKind,file,slot));runUploadQueue();return}const input=e.target.closest('[data-detail-upload-id]');if(!input||!input.files.length)return;try{const form=new FormData();for(const file of input.files)form.append('files',file);form.append('kind',input.dataset.kind);const r=await fetch('/api/flights/'+input.dataset.detailUploadId+'/files',{method:'POST',body:form});const data=await r.json();if(!r.ok)throw new Error(data.error||'Upload failed');toast(data.assigned?'Both files received · Flight ID assigned':'File uploaded successfully');if(data.flight_db_id)detailFlightId=data.flight_db_id;await load()}catch(err){toast(err.message,true)}});
